// game/src/content/schema/sourceLootGraph.ts
var SourceLootGraphInputSchema = union([SourceLootInputSchema, ActorLootInputSchema, DescendantLootInputSchema]);
var SourceLootGraphInputsSchema = refine(arr(SourceLootGraphInputSchema), (rows) => {
  const inputs = new Map(rows.map((row) => [row.id, row]));
  if (inputs.size !== rows.length) return false;
  const visiting = /* @__PURE__ */ new Set(), complete = /* @__PURE__ */ new Set();
  const visit = (id2) => {
    if (complete.has(id2)) return true;
    if (visiting.has(id2)) return false;
    const row = inputs.get(id2);
    if (!row) return false;
    visiting.add(id2);
    if ("sourceInputId" in row && !visit(row.sourceInputId)) return false;
    visiting.delete(id2);
    complete.add(id2);
    return true;
  };
  return rows.every((row) => visit(row.id));
}, "Source loot ids must be unique and all dependencies must exist without cycles");

