var WING_CENTRE = PIER_OUTER + 1;
var WING_END = PIER_OUTER + 2;
var BANNER_BRACKET_TOP_Y = 0.844;
var BANNER_HEAD_CLEARANCE = 0.06;
var BANNER_1_RAIL_DROP = BANNER_BRACKET_TOP_Y + BANNER_HEAD_CLEARANCE;

