// game/src/render/structures/parts.ts
function r32(value3) {
  return Math.round(value3 * 1e3) / 1e3;
}
function r42(value3) {
  return Math.round(value3 * 1e4) / 1e4;
}
function variantPart(tag, assetId, dx, dy, dz, rotationY = 0, scale = 1) {
  return {
    tag: tag.startsWith("v_") ? tag : `v_${tag}`,
    assetId,
    dx: r32(dx),
    dy: r32(dy),
    dz: r32(dz),
    rotationY: r42(rotationY),
    scale: r42(scale)
  };
}
function withDetails(base, ...details) {
  return [...base, ...details];
}
function mapAssets(base, select) {
  return base.map((part) => {
    const assetId = select(part);
    return assetId === void 0 || assetId === part.assetId ? part : { ...part, assetId };
  });
}
function inset(value3, halfExtent, margin = 0.25) {
  const limit = Math.max(0, halfExtent - margin);
  return Math.max(-limit, Math.min(limit, value3));
}

