// game/src/content/schema/resources.ts
var positiveRange = refine(
  tuple([num({ exclusiveMin: 0 }), num({ exclusiveMin: 0 })]),
  ([min, max]) => min <= max,
  "min must be <= max"
);
var yieldRange = refine(
  tuple([int({ min: 1 }), int({ min: 1 })]),
  ([min, max]) => min <= max,
  "min must be <= max"
);
var ResourcePresentationSchema = obj({
  availableAssetIds: arr(ref("asset"), { minLength: 1 }, { label: "Available assets", help: "Selected deterministically using the entity id." }),
  depletedAssetId: opt(ref("asset"), { label: "Depleted asset", help: "When absent, the renderer may derive a spent appearance." }),
  targetWorldSize: num({ exclusiveMin: 0 }, { label: "Target world size", unit: "m", help: "Largest world-space dimension before variant scaling." }),
  variantScale: opt(positiveRange, { label: "Variant scale", help: "Minimum and maximum deterministic size multiplier." }),
  waterOffset: opt(num(), { label: "Water offset", unit: "m" }),
  materialTier: int({ min: 0 }, { label: "Material tier", step: 1 })
});
var ResourceSchema = obj({
  id: id(),
  name: str({ nonEmpty: true }, { label: "Name" }),
  archetype: enumOf(["ore", "tree", "fishing_spot"], { label: "Archetype" }),
  skill: enumOf(SKILL_IDS, { label: "Gathering skill", ref: "skill" }),
  tier: int({ min: 0 }, { label: "Tier", step: 1 }),
  reqLevel: int({ min: 1 }, { label: "Required level", step: 1 }),
  itemId: ref("item", { label: "Yield item" }),
  bonus: opt(arr(obj({
    itemId: ref("item", { label: "Bonus item" }),
    chance: num({ min: 0, max: 1 }, { label: "Chance", help: "Probability per successful gather, between zero and one." })
  })), { label: "Bonus rolls", help: "Each secondary drop rolls independently." }),
  yieldRange: opt(yieldRange, { label: "Capacity range", help: "Optional inclusive minimum and maximum node capacity." }),
  respawnSeconds: opt(num({ min: 0 }), { label: "Respawn cooldown", unit: "s" }),
  presentation: ResourcePresentationSchema
});
var RESOURCE_SOURCE_CATALOGS = [
  "CROWNWARD_FISH_RESOURCES",
  "GATHERING_PRODUCTION_RESOURCES",
  "ESSENCE_RESOURCES",
  "HIGH_TIER_TREE_RESOURCES",
  "WILDERNESS_ORE_RESOURCES",
  "WILDERNESS_TREE_RESOURCES",
  "FAIRY_ORE_RESOURCES",
  "FAIRY_TREE_RESOURCES"
];
var ResourceRecordSchema = ResourceSchema.extend({
  catalog: enumOf(RESOURCE_SOURCE_CATALOGS, { hidden: true })
});

// game/src/content/resourceData.ts
var RESOURCE_RECORDS = parseCollection(ResourceRecordSchema, resources_default, { name: "resources" });
var RESOURCE_DATA = RESOURCE_RECORDS.map(({ catalog: _catalog, ...resource }) => resource);
var RESOURCE_BY_ID = new Map(RESOURCE_DATA.map((resource) => [resource.id, resource]));
function resourceRows(catalog2) {
  const selected = new Set(typeof catalog2 === "string" ? [catalog2] : catalog2);
  return RESOURCE_DATA.filter((_resource, index) => selected.has(RESOURCE_RECORDS[index].catalog));
}
function resourceById(resourceId) {
  const resource = RESOURCE_BY_ID.get(resourceId);
  if (!resource) throw new Error(`Unknown resource id "${resourceId}".`);
  return resource;
}

