function crownwardDragonGroup(speciesId, id2, centre) {
  const form = CROWNWARD_DRAGON_FORMS.find((entry) => entry.id === speciesId);
  const species2 = CROWNWARD_DRAGON_SPECIES.find((entry) => entry.id === speciesId);
  if (!form || !species2) throw new Error(`Unknown Crownward dragon ${speciesId}`);
  const boss2 = form.rank === "boss";
  return {
    id: id2,
    family: species2.stats.family,
    name: species2.stats.name,
    tier: 40,
    assetId: species2.assetId,
    scale: species2.scale / (boss2 ? 1.6 : 1.3),
    centre,
    count: 1,
    radius: 0,
    ...boss2 ? { boss: true } : { miniBoss: true }
  };
}
function resolveCrownwardDragonEncounters(positions) {
  return CROWNWARD_DRAGON_ENCOUNTER_INTENTS.map((intent) => {
    const centre = positions[intent.id];
    if (!centre || !centre.every(Number.isFinite)) throw new Error(`Missing finite dragon position ${intent.id}`);
    return crownwardDragonGroup(intent.speciesId, intent.id, centre);
  });
}

