// game/src/content/schema/jewelryDerivation.ts
var JewelryDerivationSchema = obj({
  kind: lit("jewelry"),
  variant: enumOf(["crafted", "miniboss"], { label: "Jewelry source" }),
  tier: int({ min: 1 }, { label: "Profile tier" }),
  shape: enumOf(["ring", "earring"], { label: "Shape" })
});
var JewelryRecipeDerivationSchema = obj({
  kind: lit("jewelryRecipe"),
  tier: int({ min: 1 }, { label: "Profile tier" }),
  shape: enumOf(["ring", "earring"], { label: "Shape" })
});

// game/src/content/schema/gearDerivation.ts
var GearDerivationSchema = discriminated("variant", {
  base: obj({
    kind: lit("gear"),
    variant: lit("base"),
    baselineId: ref("item", { label: "Baseline item" }),
    attackKind: opt(enumOf(["melee", "wand", "staff"]), { label: "Attack cadence" })
  }),
  rare: obj({
    kind: lit("gear"),
    variant: lit("rare"),
    baselineId: ref("item", { label: "Base weapon" }),
    attackKind: enumOf(["melee", "staff"], { label: "Weapon style" })
  })
});

// game/src/content/schema/itemRecords.ts
var ITEM_SOURCE_CATALOGS = [
  "CROWNWARD_FISH_ITEMS",
  "HIGH_TIER_LOG_ITEMS",
  "MAGIC_ORBS",
  "CRAFTED_JEWELRY",
  "ELEMENTAL_MAGIC_WEAPONS",
  "RARE_MINIBOSS_WEAPONS",
  "EQUIPMENT",
  "CREATURE_LOOT_ITEMS",
  "WILDERNESS_LOOT_ITEMS",
  "BOSS_ARMOR_ITEMS",
  "MINIBOSS_JEWELLERY",
  "REGIONAL_TIER_ITEMS",
  "ITEMS"
];
var ItemRecordSchema = ItemSchema.extend({
  catalog: enumOf(ITEM_SOURCE_CATALOGS, { hidden: true }),
  derivation: opt(union([GearDerivationSchema, JewelryDerivationSchema, GearProgressionDerivationSchema, ItemFormulaDerivationSchema, MaterialFoodDerivationSchema]), { label: "Balance derivation" })
});

// game/src/content/itemData.ts
var ITEM_RECORDS = parseCollection(ItemRecordSchema, items_default, { name: "items" });
var ITEM_DATA = ITEM_RECORDS.map(({ catalog: _catalog, derivation: _derivation, ...item }) => item);
function itemRows(catalog2) {
  const selected = new Set(typeof catalog2 === "string" ? [catalog2] : catalog2);
  return ITEM_DATA.filter((_item, index) => selected.has(ITEM_RECORDS[index].catalog));
}

