// game/src/content/schema/recipeDerivation.ts
var RECIPE_WEIGHT_KEYS = [
  "smeltBar",
  "dagger",
  "sword",
  "bodyOrLegs",
  "helmBootsGloves",
  "toolHead",
  "cookedFood",
  "amuletOrRing",
  "leatherBody",
  "staff",
  "wand",
  "toolHandle",
  "fishingRod",
  "woodenShield"
];
var recipeXpByWeightKey = obj({
  kind: lit("recipeXp", { readOnly: true }),
  weightKey: enumOf(RECIPE_WEIGHT_KEYS, { label: "Craft weight key" })
});
var recipeXpByLiteralWeight = obj({
  kind: lit("recipeXp", { readOnly: true }),
  craftWeight: num({ exclusiveMin: 0 }, { label: "Craft weight", unit: "x" })
});
var RecipeDerivationSchema = union([
  recipeXpByWeightKey,
  recipeXpByLiteralWeight
], { label: "XP derivation" });

// game/src/content/schema/recipes.ts
var ingredient = obj({
  itemId: ref("item", { label: "Item" }),
  quantity: int({ min: 1 }, { label: "Quantity", step: 1 })
});
var RecipeSchema = obj({
  id: id(),
  name: str({ nonEmpty: true }, { label: "Name" }),
  kind: enumOf(["smelt", "smith", "cook", "craft", "fletch"], { label: "Recipe kind" }),
  skill: enumOf(SKILL_IDS, { label: "Skill", ref: "skill" }),
  reqLevel: int({ min: 1 }, { label: "Required level", step: 1 }),
  tier: int({ min: 0 }, { label: "Tier", step: 1 }),
  stations: nullable(
    arr(enumOf([
      "furnace",
      "anvil",
      "range",
      "campfire",
      "crafting_table",
      "fletching_bench",
      "essence_altar"
    ], { label: "Station", ref: "station" }), { minLength: 1 }),
    { label: "Accepted stations", help: "Null allows production anywhere." }
  ),
  inputs: arr(ingredient, {}, { label: "Ingredients" }),
  output: ingredient.describe({ label: "Output" }),
  durationMs: num({ exclusiveMin: 0 }, { label: "Duration", unit: "ms" }),
  xp: int({ min: 0 }, { label: "XP", unit: "xp", step: 1 }),
  burntItemId: opt(ref("item"), { label: "Burnt output", help: "Item produced when cooking fails." })
});
var RECIPE_SOURCE_CATALOGS = [
  "JEWELRY_RECIPES",
  "CREATURE_LOOT_RECIPES",
  "WILDERNESS_LOOT_RECIPES",
  "CROWNWARD_FISH_RECIPES",
  "REGIONAL_TIER_RECIPES",
  "RECIPES"
];
var RecipeRecordSchema = RecipeSchema.extend({
  catalog: enumOf(RECIPE_SOURCE_CATALOGS, { hidden: true }),
  derivation: opt(union([RecipeDerivationSchema, JewelryRecipeDerivationSchema]), {
    label: "Balance derivation",
    help: "Locks the fields supplied by this recipe's source formula, including XP and base-table duration. Remove this tag to hand tune them."
  })
});

// game/src/content/recipeData.ts
var RECIPE_RECORDS = parseCollection(RecipeRecordSchema, recipes_default2, { name: "recipes" });
var RECIPE_DATA = RECIPE_RECORDS.map(({ catalog: _catalog, derivation: _derivation, ...recipe }) => recipe);
function recipeRows(catalog2) {
  const selected = new Set(typeof catalog2 === "string" ? [catalog2] : catalog2);
  return RECIPE_DATA.filter((_recipe, index) => selected.has(RECIPE_RECORDS[index].catalog));
}

