// game/src/content/fantasyEncounters.ts
var FANTASY_ENCOUNTER_SPECIES = BIOME_POPULATION_LEGACY_REPLACEMENTS;
var FANTASY_BOSS_BODIES = REGIONAL_BOSS_BODIES;
function fantasyEncounter(group) {
  const id2 = FANTASY_ENCOUNTER_SPECIES[group.id];
  if (id2) {
    const species2 = CREATURE_SPECIES.find((row) => row.id === id2);
    if (!species2) throw new Error("Missing accepted fantasy occupant " + id2 + " for " + group.id);
    return { ...group, family: species2.stats.family, name: species2.stats.name, assetId: species2.assetId, scale: species2.scale };
  }
  const body = FANTASY_BOSS_BODIES[group.id];
  if (!body) return group;
  return {
    ...group,
    assetId: body.assetId,
    scale: body.scale / tierSilhouetteScale(group.tier) / (group.boss ? 1.6 : group.miniBoss ? 1.3 : 1)
  };
}

