// game/src/content/encounterPlacement.ts
function encounterBodyRadius(group) {
  const native = ENCOUNTER_ASSET_RADII[group.assetId];
  if (!native) throw new Error(`Missing promoted encounter footprint: ${group.assetId}`);
  return native * group.scale * tierSilhouetteScale(group.tier) * (group.boss ? 1.6 : group.miniBoss ? 1.3 : 1);
}
function populationGroup(group) {
  const layout = LEGACY_ENCOUNTER_PLACEMENT_OVERRIDES[group.id];
  const count2 = group.boss || group.miniBoss ? 1 : group.countPolicy === "fixed" ? encounterPopulationCount(group) : layout?.count ?? encounterPopulationCount(group);
  const radius2 = encounterBodyRadius(group);
  return {
    ...group,
    legacyCount: group.legacyCount ?? group.count,
    count: count2,
    centre: layout?.centre ?? group.centre,
    radius: group.boss || group.miniBoss ? group.radius : layout?.radius ?? Math.max(group.radius, Math.ceil(Math.sqrt(count2) - 1) * (radius2 * 2 + 0.5) + radius2)
  };
}

